<!--
 * 定时任务（列表页）
 *
 * @path apps\cronjob-web\src\views\job\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 定时任务（列表页）
 * <p>消费后端契约 JobController（src/api/job.ts，auto-generated by bash/gen-contract.py）的任务列表页：
 * 分页查询 page、暂停 pause / 恢复 resume（按 status 显示其一）、手动触发 trigger、删除 deleteApi，
 * 以及批量暂停/恢复/删除 batchPause / batchResume / batchDelete（勾选行组装 JobBatchDTO）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYdModal } from '@ydsz/common-ui';

import { YdBadge, YdButtonBase, YdSheet, YdSheetContent, YdSheetHeader, YdSheetTitle } from '@ydsz-core/ydsz-ui';
import { h, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRouter } from 'vue-router';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import {
  batchDelete,
  batchPause,
  batchResume,
  deleteApi,
  page,
  pause,
  resume,
  trigger,
} from '#/api/job';
import { getJobEventStream } from '#/api/eventStore';
import type { JobBatchDTO, JobVO } from '#/api/models';

import { createLogger } from '@ydsz-core/shared/utils';
import JobForm from './job-form.vue';
import WebhookConfigPanel from './components/WebhookConfigPanel.vue';

const logger = createLogger('cronjob-job');

defineOptions({ name: 'JobManagement' });

const router = useRouter();
const { t } = useI18n();

/** 行类型：以真实契约 JobVO 为基础，status 由后端响应附带（契约模型未声明该字段） */
type JobRow = JobVO & { status?: string };

/** 判断任务当前是否为「已暂停」（兼容字符串/数字两种取值，未知值按运行中处理） */
function isPaused(row: JobRow): boolean {
  const status = row.status;
  return status === 'PAUSED' || status === 'DISABLED' || status === '0';
}

const gridOptions: VxeTableGridOptions<JobRow> = {
  columns: [
    { type: 'checkbox', width: 50 },
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'jobName', title: t('business.jobName'), width: 180 },
    { field: 'jobKey', title: '任务标识', width: 140 },
    { field: 'jobGroup', title: '分组', width: 100 },
    { field: 'cronExpression', title: 'Cron', width: 160 },
    { field: 'handler', title: '执行器', width: 140 },
    { field: 'jobType', title: t('business.jobType'), width: 100 },
    {
      field: 'status',
      title: t('common.status'),
      width: 90,
      slots: {
        default: ({ row }) => {
          const job = row as JobRow;
          return h(YdBadge, { variant: isPaused(job) ? 'secondary' : 'default' }, () =>
            isPaused(job) ? '已暂停' : '运行中',
          );
        },
      },
    },
    { field: 'jobRemark', title: '备注', width: 140 },
    {
      field: 'nextFireTime',
      title: '下次触发',
      width: 170,
      formatter: ({ cellValue }) => (cellValue ? String(cellValue).replace('T', ' ') : '-'),
    },
    {
      field: 'lastFireTime',
      title: '上次触发',
      width: 170,
      formatter: ({ cellValue }) => (cellValue ? String(cellValue).replace('T', ' ') : '-'),
    },
    { field: 'createdAt', title: t('common.createTime'), width: 160 },
    {
      field: 'action',
      title: t('common.actions'),
      width: 300,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const job = row as JobRow;
          return h('div', { class: 'flex gap-1' }, [
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => handleEdit(job) },
              () => t('common.edit'),
            ),
            isPaused(job)
              ? h(
                  YdButtonBase,
                  { size: 'sm', variant: 'link', onClick: () => handleResume(job) },
                  () => '恢复',
                )
              : h(
                  YdButtonBase,
                  { size: 'sm', variant: 'link', onClick: () => handlePause(job) },
                  () => '暂停',
                ),
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => handleTrigger(job) },
              () => '触发',
            ),
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => handleViewLog(job) },
              () => '日志',
            ),
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => handleViewEvents(job) },
              () => '事件流',
            ),
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => handleWebhookConfig(job) },
              () => 'WebHook',
            ),
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => handleDelete(job) },
              () => t('common.delete'),
            ),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  checkboxConfig: { highlight: true },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const res = await page({
          pageNum: pageInfo.currentPage,
          size: pageInfo.pageSize,
          ...formValues,
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'keyword',
        title: '关键词',
        itemRender: { name: 'YdInput', props: { placeholder: '任务名称/标识' } },
      },
      {
        field: 'group',
        title: '分组',
        itemRender: { name: 'YdInput', props: { placeholder: '分组' } },
      },
      {
        field: 'status',
        title: t('common.status'),
        itemRender: {
          name: 'YdSelectBase',
          props: {
            clearable: true,
            options: [
              { label: '运行中', value: 'NORMAL' },
              { label: '已暂停', value: 'PAUSED' },
              { label: '已停止', value: 'STOPPED' },
              { label: '异常', value: 'ERROR' },
            ],
          },
        },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [JobFormModal, jobFormApi] = useYdModal({ connectedComponent: JobForm });

/** Webhook 配置抽屉可见性 */
const drawerVisible = ref(false);
/** 当前选中配置 Webhook 的任务 ID */
const selectedJobId = ref<string>('');

/** 事件流抽屉可见性 */
const eventDrawerVisible = ref(false);
/** 当前查看事件流的任务 ID */
const selectedEventJobId = ref<string>('');
/** 事件流数据 */
const eventStream = ref<string[]>([]);
const eventLoading = ref(false);

/** 打开任务 Webhook 配置抽屉 */
function handleWebhookConfig(row: JobRow): void {
  selectedJobId.value = row.id ?? '';
  drawerVisible.value = true;
}

/** 打开任务事件流抽屉 */
async function handleViewEvents(row: JobRow): Promise<void> {
  if (!row.id) return;
  selectedEventJobId.value = row.id;
  eventDrawerVisible.value = true;
  eventLoading.value = true;
  try {
    eventStream.value = await getJobEventStream({ jobId: row.id });
  } catch (e) {
    logger.warn('加载事件流失败', e);
    eventStream.value = [];
  } finally {
    eventLoading.value = false;
  }
}

/** 事件类型中文映射 */
function translateEventType(type: string): string {
  const map: Record<string, string> = {
    CREATED: '创建',
    UPDATED: '更新',
    STATUS_CHANGED: '状态变更',
    TRIGGERED: '触发',
    DELETED: '删除',
    MIGRATED: '迁移',
  };
  return map[type] ?? type;
}

function handleAdd() {
  jobFormApi.open();
}

function handleEdit(row: JobRow) {
  jobFormApi.setData({ record: row });
  jobFormApi.open();
}

async function handlePause(row: JobRow) {
  if (!row.id) return;
  try {
    await pause({ id: row.id });
    showToast.success('已暂停');
    gridApi.query();
  } catch {
    logger.warn('暂停任务失败', row.id);
    // 错误提示由请求拦截器统一处理
  }
}

async function handleResume(row: JobRow) {
  if (!row.id) return;
  try {
    await resume({ id: row.id });
    showToast.success('已恢复');
    gridApi.query();
  } catch {
    logger.warn('恢复任务失败', row.id);
    // 错误提示由请求拦截器统一处理
  }
}

async function handleTrigger(row: JobRow) {
  if (!row.id) return;
  try {
    await trigger({ id: row.id }, {});
    showToast.success('触发成功');
  } catch {
    logger.warn('触发任务失败', row.id);
    // 错误提示由请求拦截器统一处理
  }
}

async function handleDelete(row: JobRow) {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(`确定删除「${row.jobName}」吗？`, { title: '删除确认', type: 'warning' });
  } catch {
    logger.warn('用户取消删除任务', row.id);
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    if (row.id) await deleteApi({ id: row.id });
    showToast.success('删除成功');
    gridApi.query();
  } catch {
    logger.warn('删除任务失败', row.id);
    // 错误已由请求拦截器展示，无需重复处理
  }
}

/** 跳转到执行日志页并预填任务标识筛选 */
function handleViewLog(row: JobRow) {
  router.push({ path: '/log/list', query: { jobKey: row.jobKey ?? '' } });
}

/** 收集勾选行的任务 ID（JobBatchDTO.jobIds），未勾选时给出提示 */
function getSelectedIds(): string[] {
  const rows = gridApi.grid.getCheckboxRecords() as JobRow[];
  const ids = rows.map((item) => item.id ?? '').filter((id) => id !== '');
  if (ids.length === 0) {
    showToast.warning('请先勾选需要操作的任务');
  }
  return ids;
}

async function handleBatchPause() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  const data: JobBatchDTO = { jobIds: ids };
  try {
    await batchPause(data);
    showToast.success('批量暂停成功');
    gridApi.query();
  } catch {
    logger.warn('批量暂停失败', ids);
    // 错误提示由请求拦截器统一处理
  }
}

async function handleBatchResume() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  const data: JobBatchDTO = { jobIds: ids };
  try {
    await batchResume(data);
    showToast.success('批量恢复成功');
    gridApi.query();
  } catch {
    logger.warn('批量恢复失败', ids);
    // 错误提示由请求拦截器统一处理
  }
}

async function handleBatchDelete() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(`确定批量删除选中的 ${ids.length} 个任务吗？`, { title: '批量删除确认', type: 'warning', });
  } catch {
    logger.warn('用户取消批量删除', ids);
    return; // 用户主动取消批量删除
  }
  // 步骤2：执行批量删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await batchDelete({ jobIds: ids } satisfies JobBatchDTO);
    showToast.success('批量删除成功');
    gridApi.query();
  } catch {
    logger.warn('批量删除失败', ids);
    // 错误已由请求拦截器展示，无需重复处理
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('page.task')">
      <template #toolbar-tools>
        <YdButtonBase @click="handleAdd">{{ t('common.create') }}</YdButtonBase>
        <YdButtonBase variant="destructive" @click="handleBatchPause">批量暂停</YdButtonBase>
        <YdButtonBase @click="handleBatchResume">批量恢复</YdButtonBase>
        <YdButtonBase variant="destructive" @click="handleBatchDelete">批量删除</YdButtonBase>
      </template>
    </Grid>
    <JobFormModal @success="gridApi.query()" />

    <!-- Webhook 配置抽屉 -->
    <YdSheet v-model:open="drawerVisible">
      <YdSheetContent side="right" class="w-[600px]">
        <YdSheetHeader>
          <YdSheetTitle>任务 WebHook 配置</YdSheetTitle>
        </YdSheetHeader>
        <WebhookConfigPanel v-if="drawerVisible" :job-id="selectedJobId" />
      </YdSheetContent>
    </YdSheet>

    <!-- 事件流抽屉 -->
    <YdSheet v-model:open="eventDrawerVisible">
      <YdSheetContent side="right" class="w-[500px]">
        <YdSheetHeader>
          <YdSheetTitle>任务事件流</YdSheetTitle>
        </YdSheetHeader>
        <div v-if="eventLoading" class="flex h-32 items-center justify-center">
          <YdBadge>加载中...</YdBadge>
        </div>
        <div v-else-if="eventStream.length === 0" class="flex h-32 items-center justify-center text-gray-400">
          暂无事件记录
        </div>
        <div v-else class="space-y-2">
          <div v-for="(event, idx) in eventStream" :key="idx" class="border-l-4 border-blue-400 pl-3">
            <div class="text-sm font-medium">{{ translateEventType(event) }}</div>
            <div class="text-xs text-gray-500">{{ event }}</div>
          </div>
        </div>
      </YdSheetContent>
    </YdSheet>
  </Page>
</template>
